mapper.select:
SELECT COUNT(*) FROM gw_family
 WHERE user_id = #{userId}
   AND relation_cd = 'CHILD'
   AND birth_dt IS NOT NULL
   AND birth_dt >= #{cutoff}

SELECT p.*, u.name AS user_name, d.dept_nm, u.email,
       u.bank_cd, u.bank_account
  FROM gw_payroll p
  JOIN gw_user u ON u.user_id = p.user_id
  LEFT JOIN gw_dept d ON d.dept_id = u.dept_id
 WHERE p.pay_month = #{payMonth}

   AND p.status_cd = #{status}

 ORDER BY d.dept_nm, u.name
 LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM gw_payroll p
 WHERE p.pay_month = #{payMonth}

   AND p.status_cd = #{status}
